@testable import Bramble
import XCTest

/// The port of the extension's `friendlyError` against what the extension itself answers
/// (`FriendlyErrorVectors`, generated by running it): the swap, revoke and multisig refusals the
/// core writes, and one raw string per branch of the classifier, in its order.
final class FriendlyErrorTests: XCTestCase {
    func testEveryPatternCompiles() {
        XCTAssertTrue(FriendlyPattern.all.allSatisfy { $0.regex != nil })
    }

    func testEachRawStringReadsAsTheExtensionShowsIt() {
        for (raw, shown) in FriendlyErrorVectors.cases {
            XCTAssertEqual(FriendlyError.message(raw), shown, "raw: \(raw)")
        }
    }

    func testPlumbingReadsTheCallersContext() {
        XCTAssertEqual(FriendlyError.message("unknown account", context: "Couldn't swap."), "Couldn't swap.")
        XCTAssertEqual(FriendlyError.message("", context: "Couldn't swap."), "Couldn't swap.")
        XCTAssertEqual(FriendlyError.message("Already a sentence.", context: "Couldn't swap."), "Already a sentence.")
    }
}
